-- Register the Execution Validation Gate tool contract of market-ai-orc in Tool_Catalog.
-- create_analysis_spec is new (v1). run_python_analysis and get_analysis_result change their input or
-- output contract (spec_id + logical inputs; separate execution and validation statuses), so they get
-- new v2 rows and their v1 rows are kept as history, marked superseded_by = v2. The seven unchanged
-- market-ai-orc rows move to runtime commit ccfef4d. Every row stays is_active = false: activation is
-- owned by the market-ai-orc registry (PY_SANDBOX_URL and a ready sandbox). Input schemas and
-- descriptions are generated from the registry; advertised ceilings mirror code defaults and the
-- sandbox configuration remains the enforcement layer.
BEGIN;

SET LOCAL lock_timeout = '5s';
SET LOCAL statement_timeout = '1min';

DO $preflight$
BEGIN
    IF EXISTS (SELECT 1 FROM public."Tool_Catalog"
               WHERE tool_name = 'create_analysis_spec'
                  OR (tool_name IN ('run_python_analysis', 'get_analysis_result') AND version = 'v2')) THEN
        RAISE EXCEPTION 'The validation gate tool rows are already registered in Tool_Catalog';
    END IF;
    IF (SELECT count(*) FROM public."Tool_Catalog"
        WHERE tool_specific_limits->>'runtime_service' = 'market-ai-orc' AND NOT is_active
          AND tool_specific_limits->>'runtime_commit' = '81475ae') <> 9 THEN
        RAISE EXCEPTION 'Expected the nine market-ai-orc rows at runtime_commit 81475ae (migration 008)';
    END IF;
    IF (SELECT count(*) FROM public."Tool_Catalog"
        WHERE tool_name IN ('run_python_analysis', 'get_analysis_result') AND version = 'v1'
          AND NOT is_active) <> 2 THEN
        RAISE EXCEPTION 'Expected inactive v1 rows of run_python_analysis and get_analysis_result';
    END IF;
END
$preflight$;

UPDATE public."Tool_Catalog"
SET tool_specific_limits = tool_specific_limits || '{"superseded_by": "v2"}'::jsonb,
    updated_at = CURRENT_TIMESTAMP
WHERE tool_name IN ('run_python_analysis', 'get_analysis_result') AND version = 'v1';

UPDATE public."Tool_Catalog"
SET tool_specific_limits = tool_specific_limits || '{"runtime_commit": "ccfef4d"}'::jsonb,
    updated_at = CURRENT_TIMESTAMP
WHERE tool_specific_limits->>'runtime_service' = 'market-ai-orc' AND NOT is_active
  AND tool_specific_limits->>'runtime_commit' = '81475ae'
  AND tool_name NOT IN ('run_python_analysis', 'get_analysis_result');

INSERT INTO public."Tool_Catalog" (
    tool_name, tool_family, tool_type, purpose, input_schema, output_schema,
    execution_type, handler_name, default_output_rows, max_output_rows,
    max_input_rows, max_tickers, max_date_range_days, max_estimated_rows,
    timeout_seconds, max_output_bytes, max_llm_result_rows,
    max_llm_result_bytes, max_llm_result_tokens,
    requires_analytics_worker, requires_feature_catalog, requires_data_readiness,
    tool_specific_limits, version, is_active
)
VALUES
    ('create_analysis_spec', 'ADVANCED', 'VALIDATION', 'Required before any Python analysis: propose the machine-readable contract of the calculation. The service checks it against the user''s own messages and returns APPROVED (with spec_id), APPROVED_WITH_UNVERIFIED (spec_id plus requirements the user did not state, which must be disclosed), ANALYSIS_SPEC_MISMATCH (fix the spec to match the request; never change the request to fit limits), NEEDS_CLARIFICATION (ask the user), or INVALID_SPEC. It also returns the resolved analysis period and required_input: the warm-up history and the date range to request with request_data. provenance per requirement: USER_EXPLICIT only for what the user stated, USER_CLARIFIED for answers to your clarification question, APPROVED_DEFAULT with default_id for a documented default, AI_INFERRED otherwise. Defaults: DEFAULT_TRAILING_CALENDAR_WINDOW (''last N months'' = TRAILING), DEFAULT_TRADING_DAYS, DEFAULT_LATEST, DEFAULT_MONTH_WITHOUT_YEAR, DEFAULT_UNIVERSE_ALL_IN_SOURCE (''all stocks''), DEFAULT_FREQUENCY_DAILY, DEFAULT_ROLLING_WINDOW_UNIT, DEFAULT_STD_DDOF (1), DEFAULT_ZSCORE_INCLUDES_CURRENT, DEFAULT_RETURN_KIND (SIMPLE), DEFAULT_RETURN_HORIZON (1), DEFAULT_RETURN_AS_PERCENT (false), DEFAULT_RSI_PERIOD (14), DEFAULT_RSI_SMOOTHING (WILDER), DEFAULT_CORRELATION_METHOD, DEFAULT_CORRELATION_TRANSFORM (SIMPLE_RETURN), DEFAULT_CORRELATION_MIN_OVERLAP. Omitted method parameters get their default. Methods with independent recalculation (params): SMA(window), ROLLING_STD(window, ddof), ROLLING_ZSCORE(window, ddof, include_current), RETURN(horizon, kind SIMPLE|LOG, as_percent), FORWARD_RETURN(horizon, kind, as_percent), RSI(period), ROLLING_CORRELATION(window, method, transform; two columns), CORRELATION(method, transform, min_overlap; ENTITY_PAIR output over a TICKERS universe). Any other research method is CUSTOM with a formula, time_alignment, optional warmup_observations param, and covers; CUSTOM results are never independently recalculated. Chain a method on another calculation with input_calculation (e.g. ROLLING_STD of a RETURN). outputs: each TABLE the code emits, by name. grain ENTITY_DATE (one row per entity and date in the period), ENTITY (one row per entity at its latest observation in the period), ENTITY_PAIR, or UNSPECIFIED (not checkable). coverage FULL (every entity/date in scope) or SELECTION (only rows meeting the selection predicates, e.g. RSI < 30). Only declared outputs with a checkable grain can pass validation.', '{"additionalProperties":false,"properties":{"analysis_period":{"additionalProperties":false,"properties":{"count":{"anyOf":[{"type":"integer"},{"type":"null"}],"description":"Units for TRAILING, dates for TRADING_DAYS, else null."},"default_id":{"anyOf":[{"type":"string"},{"type":"null"}]},"end":{"anyOf":[{"type":"string"},{"type":"null"}],"description":"YYYY-MM-DD for EXPLICIT_DATES, else null."},"mode":{"enum":["EXPLICIT_DATES","TRAILING","TRADING_DAYS","LATEST"],"type":"string"},"provenance":{"enum":["USER_EXPLICIT","USER_CLARIFIED","APPROVED_DEFAULT","AI_INFERRED"],"type":"string"},"start":{"anyOf":[{"type":"string"},{"type":"null"}],"description":"YYYY-MM-DD for EXPLICIT_DATES, else null."},"unit":{"anyOf":[{"enum":["DAY","WEEK","MONTH","YEAR"],"type":"string"},{"type":"null"}],"description":"TRAILING calendar unit, else null."}},"required":["mode","start","end","unit","count","provenance","default_id"],"type":"object"},"calculations":{"items":{"additionalProperties":false,"properties":{"columns":{"description":"Input columns ([] when input_calculation is set).","items":{"type":"string"},"type":"array"},"covers":{"anyOf":[{"items":{"enum":["RSI","SMA","STD","ZSCORE","RETURN","FORWARD_RETURN","CORRELATION"],"type":"string"},"type":"array"},{"type":"null"}],"description":"CUSTOM only: requested method families it implements."},"dataset":{"description":"Logical input name.","type":"string"},"default_id":{"anyOf":[{"type":"string"},{"type":"null"}]},"formula":{"anyOf":[{"type":"string"},{"type":"null"}],"description":"Required for CUSTOM; null for other methods."},"id":{"type":"string"},"input_calculation":{"anyOf":[{"type":"string"},{"type":"null"}],"description":"id of an earlier calculation used as input, or null."},"method":{"enum":["SMA","ROLLING_STD","ROLLING_ZSCORE","RETURN","FORWARD_RETURN","RSI","ROLLING_CORRELATION","CORRELATION","CUSTOM"],"type":"string"},"output_column":{"description":"Column holding this value in the outputs.","type":"string"},"params":{"items":{"additionalProperties":false,"properties":{"default_id":{"anyOf":[{"type":"string"},{"type":"null"}]},"name":{"type":"string"},"provenance":{"enum":["USER_EXPLICIT","USER_CLARIFIED","APPROVED_DEFAULT","AI_INFERRED"],"type":"string"},"value":{"anyOf":[{"type":"integer"},{"type":"number"},{"type":"string"},{"type":"boolean"},{"type":"null"}],"description":"The parameter value; null applies the method''s approved default (recorded as APPROVED_DEFAULT)."}},"required":["name","value","provenance","default_id"],"type":"object"},"type":"array"},"provenance":{"enum":["USER_EXPLICIT","USER_CLARIFIED","APPROVED_DEFAULT","AI_INFERRED"],"type":"string"},"time_alignment":{"anyOf":[{"type":"string"},{"type":"null"}],"description":"Required for CUSTOM; null otherwise."}},"required":["id","method","dataset","columns","input_calculation","params","output_column","formula","time_alignment","covers","provenance","default_id"],"type":"object"},"type":"array"},"exclusion_rules":{"items":{"additionalProperties":false,"properties":{"default_id":{"anyOf":[{"type":"string"},{"type":"null"}]},"provenance":{"enum":["USER_EXPLICIT","USER_CLARIFIED","APPROVED_DEFAULT","AI_INFERRED"],"type":"string"},"rule":{"enum":["MIN_OBSERVATIONS_IN_PERIOD","MAX_STALENESS_DAYS","EXCLUDE_TICKERS"],"type":"string"},"value":{"anyOf":[{"type":"integer"},{"items":{"type":"string"},"type":"array"}]}},"required":["rule","value","provenance","default_id"],"type":"object"},"type":"array"},"frequency":{"additionalProperties":false,"properties":{"default_id":{"anyOf":[{"type":"string"},{"type":"null"}]},"provenance":{"enum":["USER_EXPLICIT","USER_CLARIFIED","APPROVED_DEFAULT","AI_INFERRED"],"type":"string"},"value":{"enum":["1D","1W","1M"],"type":"string"}},"required":["value","provenance","default_id"],"type":"object"},"inputs":{"items":{"additionalProperties":false,"properties":{"columns":{"description":"Columns the analysis needs.","items":{"type":"string"},"type":"array"},"date_column":{"anyOf":[{"type":"string"},{"type":"null"}],"description":"Date column; null uses the table''s default."},"entity_column":{"anyOf":[{"type":"string"},{"type":"null"}],"description":"Entity column (e.g. ticker); null uses the table''s default."},"name":{"description":"Logical input name, e.g. prices.","type":"string"},"source_table":{"description":"Catalog table the data comes from.","type":"string"}},"required":["name","source_table","entity_column","date_column","columns"],"type":"object"},"type":"array"},"outputs":{"items":{"additionalProperties":false,"properties":{"calculations":{"items":{"type":"string"},"type":"array"},"coverage":{"enum":["FULL","SELECTION"],"type":"string"},"date_column":{"anyOf":[{"type":"string"},{"type":"null"}]},"entity_column":{"anyOf":[{"type":"string"},{"type":"null"}]},"grain":{"enum":["ENTITY_DATE","ENTITY","ENTITY_PAIR","UNSPECIFIED"],"type":"string"},"name":{"description":"The name the code passes to emit_table.","type":"string"},"pair_columns":{"anyOf":[{"items":{"type":"string"},"type":"array"},{"type":"null"}],"description":"Two entity columns for ENTITY_PAIR, else null."},"selection":{"anyOf":[{"items":{"additionalProperties":false,"properties":{"calculation":{"type":"string"},"default_id":{"anyOf":[{"type":"string"},{"type":"null"}]},"op":{"enum":[">",">=","<","<=","==","!="],"type":"string"},"provenance":{"enum":["USER_EXPLICIT","USER_CLARIFIED","APPROVED_DEFAULT","AI_INFERRED"],"type":"string"},"value":{"type":"number"}},"required":["calculation","op","value","provenance","default_id"],"type":"object"},"type":"array"},{"type":"null"}],"description":"Predicates for SELECTION, else null."}},"required":["name","grain","coverage","calculations","selection","entity_column","date_column","pair_columns"],"type":"object"},"type":"array"},"question":{"description":"The analytical request, restated.","type":"string"},"universe":{"additionalProperties":false,"properties":{"default_id":{"anyOf":[{"type":"string"},{"type":"null"}]},"provenance":{"enum":["USER_EXPLICIT","USER_CLARIFIED","APPROVED_DEFAULT","AI_INFERRED"],"type":"string"},"tickers":{"anyOf":[{"items":{"type":"string"},"type":"array"},{"type":"null"}],"description":"Upper-case tickers for TICKERS, else null."},"type":{"enum":["ALL_IN_SOURCE","TICKERS"],"type":"string"}},"required":["type","tickers","provenance","default_id"],"type":"object"}},"required":["question","universe","analysis_period","frequency","inputs","calculations","outputs","exclusion_rules"],"type":"object"}'::jsonb, '{"description":"The market-python-sandbox spec review (model view).","properties":{"clarification_needed":{},"derived_features":{},"mismatches":{},"next_action":{},"output_contract":{},"problems":{},"reference":{},"required_input":{},"resolved_period":{},"spec_id":{},"status":{},"unverified_requirements":{}},"type":"object"}'::jsonb,
     'ORCHESTRATOR', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 50, 20000, NULL, 20000, NULL,
     false, false, false, '{"approved_defaults_source":"market-python-sandbox app/spec.py APPROVED_DEFAULTS","executor_service":"market-python-sandbox","handler":"app/tools/analysis.py","intent_check":"deterministic English/Indonesian rules over the run''s own user messages","max_calculations":12,"max_exclusion_rules":8,"max_inputs":4,"max_outputs":8,"provenance_values":["USER_EXPLICIT","USER_CLARIFIED","APPROVED_DEFAULT","AI_INFERRED"],"registry_state":"Registered in market-ai-orc; is_active=false keeps it out of market-ai-backend tool lists.","request_budget_source":"market-python-sandbox PY_SANDBOX_* configuration (not model-controlled)","runtime_commit":"ccfef4d","runtime_service":"market-ai-orc","server_supplied_fields":["request_id","reference_time","timezone","user_messages"],"spec_storage":"immutable in the sandbox record store (spec_id, sha256); never PostgreSQL","statuses":["APPROVED","APPROVED_WITH_UNVERIFIED","ANALYSIS_SPEC_MISMATCH","NEEDS_CLARIFICATION","INVALID_SPEC","REQUEST_BUDGET_EXCEEDED"]}'::jsonb, 'v1', false),
    ('run_python_analysis', 'ADVANCED', 'COMPUTATION', 'Run Python analysis in an isolated sandbox against an approved spec_id. Bind every logical input of the spec to the DATASET_READY dataset_ids that hold it (several dataset_ids may form one input only if they come from the same table with identical columns). The code runs without network, subprocess, or file access outside its workspace. The helper module saniti and its functions are already imported (no import needed). Inputs are DuckDB views named after the logical inputs. load(name, columns=[...]) returns the whole input as a pandas DataFrame sorted by entity and date (date columns hold datetime.date objects; use pd.to_datetime for Timestamps), including the warm-up history before the analysis period; sql(''SELECT ... FROM prices WHERE ...'', [params]) runs DuckDB SQL (filter and aggregate in SQL; large results are refused). Compute every indicator per entity on that full date-sorted history, then keep the period rows with out = df[in_period(df)], which applies the approved period (including LATEST and trading-day periods) the same way the validator does; never cut the input to the period before computing. INPUTS lists each input''s columns; SPEC is the approved spec; ANALYSIS_START, ANALYSIS_END and REFERENCE_DATE are the resolved period. Write intermediate Parquet only to intermediate_path(name). Libraries: numpy 2, pandas 3 (groupby().apply drops the grouping columns; prefer groupby()[col].transform), polars, pyarrow, duckdb, scipy, statsmodels, matplotlib, TA-Lib (import talib). Helpers: iter_series, prepare_panel, panel_check, add_warning. Emit every spec output with emit_table(output_name, dataframe, description='''') (no other arguments); the dataframe''s columns must include the output''s entity_column, date_column or pair_columns, and the output_column of each calculation it lists. Also emit_metrics(dict), emit_chart(figure, name, title, description), emit_artifact(name, data, format). print() is not a result, and nothing the code reports about itself counts as evidence. The result has execution_status and validation_status (PASS, INCOMPLETE, FAILED, UNVERIFIED) with validation_level, reason_codes, expected_scope, actual_scope and validation_evidence; a CALCULATION_MISMATCH can carry a diagnosis naming the parameter or procedure the values match.', '{"additionalProperties":false,"properties":{"expected_outputs":{"description":"Output types the code will emit (unique).","items":{"enum":["TABLE","METRICS","CHART","ARTIFACT"],"type":"string"},"type":"array"},"inputs":{"items":{"additionalProperties":false,"properties":{"dataset_ids":{"description":"DATASET_READY dataset_ids holding this input (same table and columns).","items":{"type":"string"},"type":"array"},"duplicate_policy":{"enum":["ERROR_ON_CONFLICT","PREFER_LATEST_SNAPSHOT"],"type":"string"},"name":{"description":"A logical input name from the approved spec.","type":"string"}},"required":["name","dataset_ids","duplicate_policy"],"type":"object"},"type":"array"},"python_code":{"description":"Python source to run in the sandbox.","type":"string"},"spec_id":{"description":"spec_id of an approved analysis spec.","type":"string"}},"required":["spec_id","inputs","python_code","expected_outputs"],"type":"object"}'::jsonb, '{"description":"The market-python-sandbox v2 analysis record (model view): execution and validation are separate statuses.","properties":{"actual_scope":{},"analysis_id":{},"database_features":{},"derived_features":{},"diagnostics":{},"error":{},"execution_status":{},"expected_outputs":{},"expected_scope":{},"inputs":{},"lineage":{},"next_action":{},"outputs":{},"outputs_expire_at":{},"question":{},"reason_codes":{},"retry_after_seconds":{},"runtime_ms":{},"spec_id":{},"validation_evidence":{},"validation_level":{},"validation_status":{},"warnings":{}},"type":"object"}'::jsonb,
     'ORCHESTRATOR', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 50, 40000, 50, 40000, NULL,
     false, false, false, '{"derived_features":"exploratory artifacts only (EXPLORATORY_UNVALIDATED); never written to PostgreSQL","execution_statuses":["QUEUED","RUNNING","COMPLETED","FAILED","CANCELLED","EXPIRED"],"executor_service":"market-python-sandbox","handler":"app/tools/analysis.py","isolation":"fresh process, non-root slot user, rlimits, seccomp (no sockets/exec/fork), locked DuckDB; not a network namespace","max_code_chars":20000,"max_dataset_ids_per_input":8,"max_logical_inputs":4,"output_types":["TABLE","METRICS","CHART","ARTIFACT"],"registry_state":"Registered in market-ai-orc; is_active=false keeps it out of market-ai-backend tool lists.","runtime_commit":"ccfef4d","runtime_service":"market-ai-orc","sandbox_limits_source":"market-python-sandbox PY_SANDBOX_* configuration (not model-controlled)","table_preview_rows":50,"validation":"preflight and postflight in a separate confined validator process; independent NumPy reference recalculation for registered methods","validation_levels":["EXECUTION_ONLY","SCOPE_VERIFIED","CALCULATION_VERIFIED"],"validation_statuses":["PENDING","PASS","INCOMPLETE","FAILED","UNVERIFIED"]}'::jsonb, 'v2', false),
    ('get_analysis_result', 'ADVANCED', 'RETRIEVAL', 'Get the execution_status, validation_status, validation_level, and structured outputs of a run_python_analysis job. Waits briefly while it runs.', '{"additionalProperties":false,"properties":{"analysis_id":{"description":"analysis_id from run_python_analysis.","type":"string"}},"required":["analysis_id"],"type":"object"}'::jsonb, '{"description":"The market-python-sandbox v2 analysis record (model view): execution and validation are separate statuses.","properties":{"actual_scope":{},"analysis_id":{},"database_features":{},"derived_features":{},"diagnostics":{},"error":{},"execution_status":{},"expected_outputs":{},"expected_scope":{},"inputs":{},"lineage":{},"next_action":{},"outputs":{},"outputs_expire_at":{},"question":{},"reason_codes":{},"retry_after_seconds":{},"runtime_ms":{},"spec_id":{},"validation_evidence":{},"validation_level":{},"validation_status":{},"warnings":{}},"type":"object"}'::jsonb,
     'ORCHESTRATOR', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 50, 40000, 50, 40000, NULL,
     false, false, false, '{"execution_statuses":["QUEUED","RUNNING","COMPLETED","FAILED","CANCELLED","EXPIRED"],"executor_service":"market-python-sandbox","handler":"app/tools/analysis.py","poll_wait_seconds":20,"registry_state":"Registered in market-ai-orc; is_active=false keeps it out of market-ai-backend tool lists.","runtime_commit":"ccfef4d","runtime_service":"market-ai-orc","validation_levels":["EXECUTION_ONLY","SCOPE_VERIFIED","CALCULATION_VERIFIED"],"validation_statuses":["PENDING","PASS","INCOMPLETE","FAILED","UNVERIFIED"]}'::jsonb, 'v2', false);

DO $verify$
BEGIN
    IF (SELECT count(*) FROM public."Tool_Catalog"
        WHERE tool_specific_limits->>'runtime_service' = 'market-ai-orc' AND NOT is_active
          AND tool_specific_limits->>'runtime_commit' = 'ccfef4d') <> 10 THEN
        RAISE EXCEPTION 'Expected ten inactive market-ai-orc rows at runtime_commit ccfef4d';
    END IF;
    IF (SELECT count(*) FROM public."Tool_Catalog"
        WHERE tool_name IN ('run_python_analysis', 'get_analysis_result') AND version = 'v1'
          AND tool_specific_limits->>'superseded_by' = 'v2'
          AND tool_specific_limits->>'runtime_commit' = '81475ae') <> 2 THEN
        RAISE EXCEPTION 'Expected the two superseded v1 rows to keep runtime_commit 81475ae';
    END IF;
    IF EXISTS (SELECT 1 FROM public."Tool_Catalog"
               WHERE is_active AND tool_specific_limits->>'runtime_service' = 'market-ai-orc') THEN
        RAISE EXCEPTION 'market-ai-orc rows must stay inactive';
    END IF;
END
$verify$;

COMMIT;
